//! Documentation coverage for [`EscrowError`] (issue #1660).
//!
//! `docs/escrow-error-messages.md` is the integrator-facing reference for every stable
//! `EscrowError` code. These tests keep it in lockstep with the enum:
//!
//! * [`DOCUMENTED_ERRORS`] lists every variant as `(name, code)`. It is generated by the
//!   `escrow_error_table!` macro together with an exhaustive `match` (no wildcard arm), so
//!   adding a variant to `EscrowError` without adding it here fails to **compile**.
//! * Each entry's code is checked against `EscrowError::X as u32`, so a wrong code in the
//!   list fails.
//! * Each `(name, code)` pair must appear on the **same table row** of the docs, so a missing
//!   entry or a wrong code in the docs fails.
//! * Numeric codes must be unique, both in the list and in the docs.
//!
//! When you add a variant: add it to `EscrowError`, add `Name = code,` below, and add a
//! `| `Name` | code | description |` row to `docs/escrow-error-messages.md`.

use crate::EscrowError;
use std::collections::{BTreeMap, BTreeSet};

/// The error reference, embedded at compile time so the test cannot drift from the file.
const ERROR_DOCS: &str = include_str!("../../../docs/escrow-error-messages.md");

macro_rules! escrow_error_table {
    ($($name:ident = $code:literal,)+) => {
        /// Every `EscrowError` variant as `(name, code, variant)`.
        const DOCUMENTED_ERRORS: &[(&str, u32, EscrowError)] = &[
            $((stringify!($name), $code, EscrowError::$name),)+
        ];

        /// Exhaustive by construction: no wildcard arm, so a new `EscrowError` variant that is
        /// not listed in `escrow_error_table!` is a compile error (E0004).
        fn listed_code(err: EscrowError) -> u32 {
            match err {
                $(EscrowError::$name => $code,)+
            }
        }
    };
}

