/// Parses `| `Name` | code | ... |` table rows into `(name, code)` pairs, in file order.
fn doc_rows(doc: &str) -> Vec<(String, u32)> {
    doc.lines()
        .filter_map(|line| {
            let mut cells = line.trim().strip_prefix('|')?.split('|').map(str::trim);
            let name = cells.next()?.strip_prefix('`')?.strip_suffix('`')?;
            let code = cells.next()?.parse::<u32>().ok()?;
            Some((name.to_string(), code))
        })
        .collect()
}

/// Every way `doc` disagrees with [`DOCUMENTED_ERRORS`]; empty when in sync.
fn doc_problems(doc: &str) -> Vec<String> {
    let rows = doc_rows(doc);
    let mut problems = Vec::new();

    let mut by_name: BTreeMap<&str, Vec<u32>> = BTreeMap::new();
    let mut by_code: BTreeMap<u32, Vec<&str>> = BTreeMap::new();
    for (name, code) in &rows {
        by_name.entry(name.as_str()).or_default().push(*code);
        by_code.entry(*code).or_default().push(name.as_str());
    }

    for (name, code, _) in DOCUMENTED_ERRORS {
        match by_name.get(name) {
            None => problems.push(format!("`{name}` ({code}) is not documented")),
            Some(codes) if !codes.contains(code) => problems.push(format!(
                "`{name}` is documented with code(s) {codes:?}, expected {code}"
            )),
            Some(_) => {}
        }
    }
    for (name, codes) in &by_name {
        if codes.len() > 1 {
            problems.push(format!("`{name}` has {} rows in the docs", codes.len()));
        }
        if !DOCUMENTED_ERRORS.iter().any(|(n, _, _)| n == name) {
            problems.push(format!(
                "`{name}` is documented but is not an EscrowError variant"
            ));
        }
    }
    for (code, names) in &by_code {
        if names.len() > 1 {
            problems.push(format!(
                "code {code} is documented for several names: {names:?}"
            ));
        }
    }
    problems
}

#[test]
fn table_matches_enum_discriminants() {
    for (name, code, err) in DOCUMENTED_ERRORS {
        assert_eq!(
            *err as u32, *code,
            "`{name}`: listed code differs from EscrowError::{name} as u32"
        );
        assert_eq!(
            listed_code(*err),
            *code,
            "`{name}`: exhaustive match disagrees with table"
        );
    }
}

#[test]
fn table_has_unique_names_and_codes() {
    let mut names = BTreeSet::new();
    let mut codes = BTreeSet::new();
    for (name, code, _) in DOCUMENTED_ERRORS {
        assert!(names.insert(*name), "`{name}` listed twice");
        assert!(
            codes.insert(*code),
            "code {code} listed twice (at `{name}`)"
        );
    }
}

#[test]
fn every_escrow_error_is_documented_with_its_code() {
    let problems = doc_problems(ERROR_DOCS);
    assert!(
        problems.is_empty(),
        "docs/escrow-error-messages.md is out of sync with EscrowError:\n  {}",
        problems.join("\n  ")
    );
}

#[test]
fn docs_have_no_duplicate_codes() {
    let mut seen: BTreeMap<u32, String> = BTreeMap::new();
    for (name, code) in doc_rows(ERROR_DOCS) {
        if let Some(prev) = seen.insert(code, name.clone()) {
            panic!("code {code} documented for both `{prev}` and `{name}`");
        }
    }
    assert_eq!(seen.len(), DOCUMENTED_ERRORS.len());
}

// --- Checker self-tests: prove the guard actually fails on drift. ---

fn without_row(doc: &str, name: &str) -> String {
    let needle = format!("| `{name}` |");
    doc.lines()
        .filter(|l| !l.trim_start().starts_with(&needle))
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn checker_flags_an_undocumented_variant() {
    let doc = without_row(ERROR_DOCS, "PayoutZero");
    assert_eq!(
        doc_problems(&doc),
        vec!["`PayoutZero` (170) is not documented".to_string()]
    );
}

#[test]
fn checker_flags_a_wrong_code_on_the_row() {
    let doc = ERROR_DOCS.replace("| `PayoutZero` | 170 |", "| `PayoutZero` | 171 |");
    let problems = doc_problems(&doc);
    assert!(
        problems
            .iter()
            .any(|p| p.contains("`PayoutZero` is documented with code(s) [171], expected 170")),
        "{problems:?}"
    );
    assert!(
        problems
            .iter()
            .any(|p| p.starts_with("code 171 is documented for several names")),
        "{problems:?}"
    );
}

#[test]
fn checker_flags_an_unknown_name() {
    let doc = format!("{ERROR_DOCS}\n| `NotARealError` | 9999 | bogus |\n");
    assert_eq!(
        doc_problems(&doc),
        vec!["`NotARealError` is documented but is not an EscrowError variant".to_string()]
    );
}
